// Browser TLS and HTTP/2 fingerprint profiles.
//
// The TLS ClientHello is generated with uTLS using the same browser family as
// the session's User-Agent. The HTTP/2 connection preface (SETTINGS,
// WINDOW_UPDATE, PRIORITY frames and pseudo-header order) is generated by the
// minimal HTTP/2 client in http2.go using the matching profile below.
package main

import (
	"context"
	"crypto/tls"
	"fmt"
	"math/rand/v2"
	"net"
	"strconv"
	"strings"

	utls "github.com/refraction-networking/utls"
	"golang.org/x/net/http2"
)

// fingerprintKind identifies the browser family used for a connection.
type fingerprintKind int

const (
	fpNone fingerprintKind = iota
	fpChrome
	fpFirefox
	fpSafari
	fpIOS
)

// h2Priority is one PRIORITY frame sent during the HTTP/2 connection preface.
type h2Priority struct {
	streamID  uint32
	dep       uint32
	weight    uint8
	exclusive bool
}

// h2Profile describes the browser-specific HTTP/2 startup fingerprint.
type h2Profile struct {
	settings     []http2.Setting
	windowUpdate uint32
	priorities   []h2Priority
	// pseudoOrder lists pseudo-header initials in transmission order:
	// m=:method, a=:authority, s=:scheme, p=:path.
	pseudoOrder string
}

// sessionFingerprint bundles the TLS ClientHello and HTTP/2 profile selected
// for one connection.
type sessionFingerprint struct {
	kind  fingerprintKind
	hello utls.ClientHelloID
	h2    h2Profile
}

func h2ProfileFor(kind fingerprintKind) h2Profile {
	switch kind {
	case fpFirefox:
		// Firefox: 1:65536;4:131072;5:16384, WU 12517377, priority tree,
		// pseudo-header order m,p,a,s.
		return h2Profile{
			settings: []http2.Setting{
				{ID: http2.SettingHeaderTableSize, Val: 65536},
				{ID: http2.SettingInitialWindowSize, Val: 131072},
				{ID: http2.SettingMaxFrameSize, Val: 16384},
			},
			windowUpdate: 12517377,
			priorities: []h2Priority{
				// PriorityParam.Weight is zero-indexed on the wire, so the
				// values below produce browser weights 201, 101, 1, 1, 1, 241.
				{streamID: 3, dep: 0, weight: 200},
				{streamID: 5, dep: 0, weight: 100},
				{streamID: 7, dep: 0, weight: 0},
				{streamID: 9, dep: 7, weight: 0},
				{streamID: 11, dep: 3, weight: 0},
				{streamID: 13, dep: 0, weight: 240},
			},
			pseudoOrder: "mpas",
		}
	case fpSafari, fpIOS:
		// Safari/CFNetwork: ENABLE_PUSH=0, MAX_CONCURRENT_STREAMS=100,
		// INITIAL_WINDOW_SIZE=2097152, ENABLE_CONNECT_PROTOCOL=1,
		// NO_RFC7540_PRIORITIES=1, WU 10420225, pseudo-header order m,s,a,p.
		return h2Profile{
			settings: []http2.Setting{
				{ID: http2.SettingEnablePush, Val: 0},
				{ID: http2.SettingMaxConcurrentStreams, Val: 100},
				{ID: http2.SettingInitialWindowSize, Val: 2097152},
				{ID: http2.SettingEnableConnectProtocol, Val: 1},
				{ID: http2.SettingNoRFC7540Priorities, Val: 1},
			},
			windowUpdate: 10420225,
			pseudoOrder:  "msap",
		}
	default: // Chrome
		// Chrome: 1:65536;2:0;4:6291456;6:262144, WU 15663105, no priority
		// frames, pseudo-header order m,a,s,p.
		return h2Profile{
			settings: []http2.Setting{
				{ID: http2.SettingHeaderTableSize, Val: 65536},
				{ID: http2.SettingEnablePush, Val: 0},
				{ID: http2.SettingInitialWindowSize, Val: 6291456},
				{ID: http2.SettingMaxHeaderListSize, Val: 262144},
			},
			windowUpdate: 15663105,
			pseudoOrder:  "masp",
		}
	}
}

// fingerprintKindForProfile derives the TLS/HTTP2 family from the session UA.
func fingerprintKindForProfile(p uaProfile) fingerprintKind {
	switch {
	case p.firefox:
		return fpFirefox
	case p.chrome:
		return fpChrome
	case strings.Contains(p.ua, "iPhone"), strings.Contains(p.ua, "iPad"),
		strings.Contains(p.ua, "CPU OS"):
		return fpIOS
	default:
		return fpSafari
	}
}

// clientHelloForProfile picks the closest uTLS ClientHello for a UA.
func clientHelloForProfile(p uaProfile) utls.ClientHelloID {
	switch fingerprintKindForProfile(p) {
	case fpFirefox:
		v := uaVersionAfter(p.ua, "Firefox/")
		if v == 0 {
			v = uaVersionAfter(p.ua, "rv:")
		}
		switch {
		case v >= 120:
			return utls.HelloFirefox_120
		case v >= 105:
			return utls.HelloFirefox_105
		case v >= 102:
			return utls.HelloFirefox_102
		case v >= 99:
			return utls.HelloFirefox_99
		default:
			return utls.HelloFirefox_102
		}
	case fpChrome:
		v := uaVersionAfter(p.ua, "Chrome/")
		switch {
		case v >= 133:
			return utls.HelloChrome_133
		case v >= 131:
			return utls.HelloChrome_131
		case v >= 120:
			return utls.HelloChrome_120
		default:
			return utls.HelloChrome_133
		}
	case fpIOS:
		v := uaVersionAfter(p.ua, "iPhone OS ")
		if v == 0 {
			v = uaVersionAfter(p.ua, "CPU OS ")
		}
		switch {
		case v >= 14:
			return utls.HelloIOS_14
		case v >= 13:
			return utls.HelloIOS_13
		default:
			return utls.HelloIOS_12_1
		}
	default:
		return utls.HelloSafari_16_0
	}
}

// fingerprintForConfig resolves the fingerprint for a connection. A nil
// session (used by tests) falls back to the configured mode.
func fingerprintForConfig(cfg StressConfig) sessionFingerprint {
	if strings.EqualFold(cfg.Fingerprint, "none") {
		return sessionFingerprint{kind: fpNone}
	}
	p := uaProfile{}
	if cfg.session != nil {
		p = cfg.session.profile
	} else {
		p = newProfileForMode(cfg.Fingerprint)
	}
	kind := fingerprintKindForProfile(p)
	return sessionFingerprint{
		kind:  kind,
		hello: clientHelloForProfile(p),
		h2:    h2ProfileFor(kind),
	}
}

func defaultChromeFingerprint() sessionFingerprint {
	return sessionFingerprint{
		kind:  fpChrome,
		hello: utls.HelloChrome_133,
		h2:    h2ProfileFor(fpChrome),
	}
}

// newProfileForMode returns a UA profile for the requested fingerprint mode.
func newProfileForMode(mode string) uaProfile {
	switch strings.ToLower(strings.TrimSpace(mode)) {
	case "chrome":
		return makeUAProfile(generateChromeDesktopUA())
	case "firefox":
		return makeUAProfile(generateFirefoxDesktopUA())
	case "safari":
		return makeUAProfile(generateSafariDesktopUA())
	case "ios":
		return makeUAProfile(generateSafariIOSUA())
	default:
		return uaProfiles[rand.IntN(len(uaProfiles))]
	}
}

// utlsConn wraps a uTLS connection and records the negotiated ALPN protocol.
// It still implements net.Conn through the embedded *utls.UConn.
type utlsConn struct {
	*utls.UConn
	proto string
}

func (c *utlsConn) NegotiatedProtocol() string { return c.proto }

// alpnConn is implemented by TLS connections that expose the negotiated
// application protocol.
type alpnConn interface {
	NegotiatedProtocol() string
}

func isHTTP2Conn(conn net.Conn) bool {
	c, ok := conn.(alpnConn)
	return ok && c.NegotiatedProtocol() == http2.NextProtoTLS
}

// tlsHandshake upgrades raw to TLS. When fp.kind is fpNone, crypto/tls is used
// with an HTTP/1.1-only ALPN list, so disabling fingerprint mimicry also
// disables HTTP/2 (the Go ClientHello would not match the HTTP/2 profile).
func tlsHandshake(ctx context.Context, raw net.Conn, serverName string, fp sessionFingerprint, http2Enabled bool) (net.Conn, error) {
	if fp.kind == fpNone {
		cfg := &tls.Config{
			ServerName:         serverName,
			InsecureSkipVerify: true, //nolint:gosec // intentional for a stress tool
			MinVersion:         tls.VersionTLS12,
			CipherSuites:       chromeCipherSuites,
			NextProtos:         []string{"http/1.1"},
		}
		conn := tls.Client(raw, cfg)
		if err := conn.HandshakeContext(ctx); err != nil {
			_ = raw.Close()
			return nil, fmt.Errorf("TLS handshake: %w", err)
		}
		return conn, nil
	}

	nextProtos := []string{"http/1.1"}
	if http2Enabled {
		nextProtos = []string{"h2", "http/1.1"}
	}
	cfg := &utls.Config{
		ServerName:         serverName,
		InsecureSkipVerify: true, //nolint:gosec // intentional for a stress tool
		MinVersion:         utls.VersionTLS12,
		NextProtos:         nextProtos,
	}
	conn := utls.UClient(raw, cfg, fp.hello)

	// Browser presets hard-code ALPN as h2,http/1.1. When HTTP/2 is disabled,
	// rewrite the extension before the handshake so the server only selects
	// HTTP/1.1; otherwise it could negotiate h2 that this mode cannot speak.
	if !http2Enabled {
		if err := conn.BuildHandshakeState(); err != nil {
			_ = raw.Close()
			return nil, fmt.Errorf("TLS client hello: %w", err)
		}
		for _, ext := range conn.Extensions {
			if alpn, ok := ext.(*utls.ALPNExtension); ok {
				alpn.AlpnProtocols = []string{"http/1.1"}
			}
		}
	}

	if err := conn.HandshakeContext(ctx); err != nil {
		_ = raw.Close()
		return nil, fmt.Errorf("TLS handshake: %w", err)
	}
	return &utlsConn{UConn: conn, proto: conn.ConnectionState().NegotiatedProtocol}, nil
}

// uaVersionAfter extracts the first integer following marker in ua.
func uaVersionAfter(ua, marker string) int {
	i := strings.Index(ua, marker)
	if i < 0 {
		return 0
	}
	rest := ua[i+len(marker):]
	n := 0
	for n < len(rest) && rest[n] >= '0' && rest[n] <= '9' {
		n++
	}
	if n == 0 {
		return 0
	}
	v, err := strconv.Atoi(rest[:n])
	if err != nil {
		return 0
	}
	return v
}
